"""R09 §0.1 item 2: every report table is generated here from the persisted outputs. Writes R09/tables/*.md and tables/sources.json."""
from __future__ import annotations
import json, os, sys
import numpy as np, pandas as pd
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import r09_common as R9, r04_common as C4
TAB = R9.TABLES; os.makedirs(TAB, exist_ok=True); SRC = {}
def emit(name, src, lines): SRC[name] = src; open(f"{TAB}/{name}.md", "w").write(f"<!-- generated by report_tables_r09.py from {src} -->\n" + "\n".join(lines) + "\n"); print(f"wrote tables/{name}.md")
def f(x, d=3, sign=False):
    if x is None or (isinstance(x, float) and not np.isfinite(x)): return "—"
    if isinstance(x, (int, np.integer)): return f"{x:,}"
    return f"{x:+.{d}f}" if sign else f"{x:.{d}f}"
def ci(r): return f"{f(r['value'])} [{f(r['ci95'][0])}, {f(r['ci95'][1])}] (n {r['n_units']})" if r.get("n_units") else "—"
def cmp2(c): return "— | — | — | —" if not c.get("n_units") else f"{c['diff_median']:+.3f} [{c['ci95'][0]:+.3f}, {c['ci95'][1]:+.3f}] | {c['paired_median']:+.3f} [{c['paired_ci95'][0]:+.3f}, {c['paired_ci95'][1]:+.3f}] | {c['units_a_better']} / {c['units_b_better']} of {c['n_units']} | {c['sign_test_p_one_sided']:.3f}"
star = lambda u: f"{u}{' *' if u in R9.SIX else ''}"
S = json.load(open(f"{R9.OUT_SCORES}/scores_r09.json")); PI = json.load(open(f"{R9.OUT_INT}/pairs.json")); PP = pd.DataFrame(PI["pairs"]); CU = pd.read_csv(f"{R9.OUT_SCORES}/coverage_per_unit.csv")
CAND = S["candidates"]; PREDS = list(CAND.values()); LAB = {v: k for k, v in CAND.items()}
# coverage per pair / unit
L = ["| unit | pair | hr_res (m) | D1 (px) | D125 (px) | tiles | interior tiles D1 (R08b) | A_fine_int D1 defined | interior tiles D125 | A_fine_int D125 defined | median A_fine all / int D1 / int D125 (m) |", "|---|---|---|---|---|---|---|---|---|---|---|"]
for r in PP.sort_values(["unit", "pair"]).itertuples(): L.append(f"| {star(r.unit) if r.unit != 'lu16' else 'lu16 (EW0207)'} | {r.pair} | {r.hr_res_m:.2f} | {r.D1_px} | {r.D125_px} | {r.n_tiles} | {r.n_interior_D1} | {r.n_defined_int_D1} | {r.n_interior_D125} | {r.n_defined_int_D125} | {r.A_fine_median_all:.4f} / {f(r.A_fine_int_D1_median, 4)} / {f(r.A_fine_int_D125_median, 4)} |")
emit("coverage_per_pair", "targets_int/pairs.json (build_int_r09.py)", L)
L = ["| unit | tiles | interior tiles D1 (R08b) | A_fine_int D1 defined | gain | interior tiles D125 | A_fine_int D125 defined |", "|---|---|---|---|---|---|---|"]
for r in CU.itertuples(): L.append(f"| {star(r.unit) if r.unit != 'lu16' else 'lu16 (EW0207)'} | {r.n_tiles:,} | {int(r.interior_D1):,} ({r.interior_D1 / r.n_tiles:.2f}) | {int(r.defined_int_D1):,} ({r.defined_int_D1 / r.n_tiles:.2f}) | {int(r.defined_int_D1 - r.interior_D1):+,} | {int(r.interior_D125):,} ({r.interior_D125 / r.n_tiles:.2f}) | {int(r.defined_int_D125):,} ({r.defined_int_D125 / r.n_tiles:.2f}) |")
for name, uset in R9.UNIT_SETS.items():
    d = CU[CU.unit.isin(uset)]; L.append(f"| **{name}** | {d.n_tiles.sum():,} | {int(d.interior_D1.sum()):,} ({d.interior_D1.sum() / d.n_tiles.sum():.2f}) | {int(d.defined_int_D1.sum()):,} ({d.defined_int_D1.sum() / d.n_tiles.sum():.2f}) | {int(d.defined_int_D1.sum() - d.interior_D1.sum()):+,} | {int(d.interior_D125.sum()):,} ({d.interior_D125.sum() / d.n_tiles.sum():.2f}) | {int(d.defined_int_D125.sum()):,} ({d.defined_int_D125.sum() / d.n_tiles.sum():.2f}) |")
emit("coverage_per_unit", "scores/coverage_per_unit.csv (score_r09.py)", L)
# A2 scores per set
VL = {"all_Afine": "(i) all tiles, A_fine", "intD1_Afine": "(ii) interior tiles D1, A_fine (R08b)", "intpx_D1": "(iii) A_fine_int at D1", "intD125_Afine": "A3: interior tiles D125, A_fine", "intpx_D125": "A3: A_fine_int at D125"}
for name in R9.UNIT_SETS:
    L = ["| candidate | " + " | ".join(VL[v] for v in VL) + " | (iii) − (ii): Δ of medians [CI] | paired median Δ [CI] | better / worse | p |", "|---|" + "---|" * (len(VL) + 4)]
    for p in PREDS: L.append(f"| {LAB[p]} ({p}) | " + " | ".join(ci(S["median"][name][v][p]) for v in VL) + f" | {cmp2(S['intpx_minus_intD1'][name][p])} |")
    emit(f"scores_{name}", f"scores/scores_r09.json:median,intpx_minus_intD1[{name}] (score_r09.py); lu14 out of every median", L)
    uset = [u for u in R9.UNIT_SETS[name]]; L = ["| candidate | " + " | ".join(f"{star(u)} (i) / (ii) / (iii) / D125 tiles / D125 px" for u in uset) + " |", "|---|" + "---|" * len(uset)]
    for p in PREDS: L.append(f"| {LAB[p]} | " + " | ".join(" / ".join(f(S["per_unit"][v][p][u], 2, True) for v in VL) for u in uset) + " |")
    emit(f"per_unit_{name}", "scores/scores_r09.json:per_unit (score_r09.py)", L)
v = S["validation"]
emit("validation", "scores/scores_r09.json:validation (score_r09.py)", ["| candidate | paired median Δ (A_fine_int D1 − interior tiles D1), primary units scored both ways | n units | |Δ| ≤ 0.05 |", "|---|---|---|---|", f"| s_lr | {v['s_lr']['paired_median']:+.3f} [{v['s_lr']['ci95'][0]:+.3f}, {v['s_lr']['ci95'][1]:+.3f}] | {v['s_lr']['n_units']} | {'yes' if v['s_lr']['passes'] else 'no'} |", f"| GBT_ship | {v['GBT_ship']['paired_median']:+.3f} [{v['GBT_ship']['ci95'][0]:+.3f}, {v['GBT_ship']['ci95'][1]:+.3f}] | {v['GBT_ship']['n_units']} | {'yes' if v['GBT_ship']['passes'] else 'no'} |", f"| **fallback validated** | | | **{'yes' if v['validated'] else 'no'}** |"])
L = ["| unit set | candidate | D125 interior tiles − all tiles: Δ of medians [CI] | paired median Δ [CI] | better / worse | p | A_fine_int D125 − all tiles: paired median Δ [CI] | better / worse |", "|---|---|---|---|---|---|---|---|"]
for name in R9.UNIT_SETS:
    for p in PREDS: a = S["intD125_minus_all"][name][p]; b = S["intpx125_minus_all"][name][p]; L.append(f"| {name} | {LAB[p]} | {cmp2(a)} | {f(b.get('paired_median'), sign=True)} [{f(b.get('paired_ci95', [np.nan, np.nan])[0], sign=True)}, {f(b.get('paired_ci95', [np.nan, np.nan])[1], sign=True)}] | {b.get('units_a_better', '—')} / {b.get('units_b_better', '—')} of {b.get('n_units', 0)} |")
emit("stress_D125", "scores/scores_r09.json:intD125_minus_all,intpx125_minus_all (score_r09.py)", L)
emit("lu14", "scores/scores_r09.json:lu14 (score_r09.py)", ["| candidate | " + " | ".join(VL[v] for v in VL) + " |", "|---|" + "---|" * len(VL)] + [f"| {LAB[p]} | " + " | ".join(f(S["lu14"][v][p], 3, True) for v in VL) + " |" for p in PREDS])
# artifacts
A = json.load(open(f"{R9.OUT_ART}/gbt_ship_all16_record.json")); H = json.load(open(f"{R9.OUT_SCORES}/lockbox_history.json")); prov = sorted(os.listdir(R9.PROV)); last = json.load(open(f"{R9.PROV}/{[p for p in prov if p.startswith('score_r09')][-1]}"))
pv1 = last["fixed_inputs_r09"]["pv1_all"]
L = ["| candidate | artifact | sha256 | configuration / note |", "|---|---|---|---|", "| s_lr | `preprocessing/extract_clean_patches.py:build_inputs` (`s_lr = max(SD of valid LR cells in the 256-px window, 0.5 m)`), the tiles_v1.1 `s_lr` column = `ref_s_lr` | `tiles_v1_1.parquet` " + json.load(open(f"{R9.R8.DR}/R05/freeze_record.json")).get("tiles_v1_1_parquet", "see R05 §6") + " | no fitting; computed from LR only |",
     f"| GBT_ship (all 16) | `{os.path.relpath(A['artifact'], R9.ROOT)}` (OAK `R09/artifacts/`) | `{A['sha256']}` | cfg {A['cfg_idx']}: {A['config']}; inner criterion median ρ {A['inner_criterion_median_rho']:.3f}; {A['n_train_rows']} capped rows of {A['n_rows_total']}; R05's EW0207 configuration (mode of the fold choices, {A['r05_ew0207_model']['mode_count']} / 16) = cfg {A['r05_ew0207_model']['cfg_idx_mode']}: same = {A['r05_ew0207_model']['same_as_inner_choice']}; max \\|Δ\\| vs R05 EW0207 predictions {A['r05_ew0207_model']['max_abs_diff_vs_r05_ew0207_pred_m']:.2e} m; sklearn {A['sklearn_version']} |"]
for s, d in pv1.items(): L.append(f"| P-V1 seed {s} | `R07/models/P-V1/seed{s}/fold_ALL/ckpt.pt` (scratch and OAK `R07/models/`) | `{d['ckpt.pt']}` | R07 all-unit fine-tuning (init = P-V1 body); seed-averaged as R07 (mean log₁₀ block predictions, tile = RMS of 16 blocks) |")
emit("artifacts", "artifacts/gbt_ship_all16_record.json, provenance (R07/models SHA256SUMS), R05 freeze record", L)
L = ["| evidence | file (sha256) | lines |", "|---|---|---|"] + [f"| {e['label']} | `{e['path']}` (`{e['sha256'][:16]}…`) | " + "<br>".join(f"L{n}: {t.replace('|', '\\|')}" for n, t in e["lines"][:6]) + " |" for e in H["evidence"]]
emit("lockbox_history", "scores/lockbox_history.json (lockbox_history_r09.py)", L)
# ledger
TIp = pd.read_parquet(f"{R9.OUT_INT}/tiles_int.parquet"); n = len(TIp)
L = ["| stage | item | count | reason |", "|---|---|---|---|", f"| A1 | tiles with A_fine_int undefined at D1 | {int(TIp.A_fine_int_D1.isna().sum()):,} of {n:,} | < 2,048 interior px |", f"| A1 | tiles with A_fine_int undefined at D125 | {int(TIp.A_fine_int_D125.isna().sum()):,} of {n:,} | < 2,048 interior px at the 125 m distance |",
     f"| A2 | units out of every median | 1 | lu14 (no interior tile, ruling §0.3); shown in tables/lu14.md |"]
for vname in ("intpx_D1", "intD125_Afine", "intpx_D125"):
    for p in PREDS: el = set(S["eligible"][vname][p]); gone = [q for q in C4.DEV_PAIRS if q not in el]; L.append(f"| A2/A3 | pairs ineligible, {VL[vname]}, {LAB[p]} | {len(gone)} of 38 | {', '.join(gone) if gone else '—'} |")
emit("ledger", "targets_int/tiles_int.parquet, scores/scores_r09.json:eligible", L)
json.dump(SRC, open(f"{TAB}/sources.json", "w"), indent=1); print("wrote tables/sources.json")
